package fileserver

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

var (
	ErrAccessDenied  = errors.New("access denied")
	ErrNotFound      = errors.New("file not found")
	ErrInvalidToken  = errors.New("invalid access token")
	ErrRateLimited   = errors.New("rate limited")
)

// SecureFileServer serves files from a restricted base directory
// with authentication, rate limiting, and path traversal protection.
type SecureFileServer struct {
	baseDir       string
	authTokens    map[string]time.Time
	mu            sync.RWMutex
	rateLimit     map[string]*rateBucket
	rateMu        sync.Mutex
	auditLog      []auditEntry
	auditMu       sync.Mutex
	maxFileSize   int64
	allowedExts   map[string]bool
}

type rateBucket struct {
	tokens    float64
	lastCheck time.Time
	rate      float64
	capacity  float64
}

type auditEntry struct {
	Timestamp time.Time
	ClientIP  string
	Path      string
	Result    string
}

func NewSecureFileServer(baseDir string) (*SecureFileServer, error) {
	// Resolve the base directory to absolute path
	absBase, err := filepath.Abs(baseDir)
	if err != nil {
		return nil, fmt.Errorf("failed to resolve base directory: %w", err)
	}

	// Verify base directory exists and is a directory
	info, err := os.Stat(absBase)
	if err != nil {
		return nil, fmt.Errorf("base directory error: %w", err)
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("base path is not a directory: %s", absBase)
	}

	// Canonicalize the base directory path
	canonicalBase := filepath.Clean(absBase)

	return &SecureFileServer{
		baseDir:     canonicalBase,
		authTokens:  make(map[string]time.Time),
		rateLimit:   make(map[string]*rateBucket),
		maxFileSize: 50 * 1024 * 1024, // 50MB
		allowedExts: map[string]bool{
			".txt": true, ".pdf": true, ".png": true,
			".jpg": true, ".csv": true, ".json": true,
		},
	}, nil
}

// GenerateToken creates a time-limited access token
func (s *SecureFileServer) GenerateToken(duration time.Duration) (string, error) {
	bytes := make([]byte, 32)
	if _, err := rand.Read(bytes); err != nil {
		return "", err
	}
	token := hex.EncodeToString(bytes)

	s.mu.Lock()
	s.authTokens[token] = time.Now().Add(duration)
	s.mu.Unlock()

	return token, nil
}

func (s *SecureFileServer) validateToken(token string) error {
	if len(token) != 64 {
		return ErrInvalidToken
	}

	s.mu.RLock()
	expiry, exists := s.authTokens[token]
	s.mu.RUnlock()

	if !exists {
		return ErrInvalidToken
	}
	if time.Now().After(expiry) {
		s.mu.Lock()
		delete(s.authTokens, token)
		s.mu.Unlock()
		return ErrInvalidToken
	}
	return nil
}

func (s *SecureFileServer) checkRateLimit(clientIP string) error {
	s.rateMu.Lock()
	defer s.rateMu.Unlock()

	bucket, exists := s.rateLimit[clientIP]
	if !exists {
		bucket = &rateBucket{
			tokens:    10.0,
			lastCheck: time.Now(),
			rate:      2.0,  // 2 tokens per second
			capacity:  10.0, // burst of 10
		}
		s.rateLimit[clientIP] = bucket
	}

	now := time.Now()
	elapsed := now.Sub(bucket.lastCheck).Seconds()
	bucket.tokens += elapsed * bucket.rate
	if bucket.tokens > bucket.capacity {
		bucket.tokens = bucket.capacity
	}
	bucket.lastCheck = now

	if bucket.tokens < 1.0 {
		return ErrRateLimited
	}
	bucket.tokens -= 1.0
	return nil
}

// sanitizePath performs comprehensive path validation to prevent
// directory traversal attacks. It validates against multiple attack vectors:
// - Null bytes
// - Double encoding
// - Path traversal sequences
// - Symbolic link resolution
// - Prefix validation against base directory
func (s *SecureFileServer) sanitizePath(requestedPath string) (string, error) {
	// Block null bytes
	if strings.ContainsRune(requestedPath, '\x00') {
		return "", ErrAccessDenied
	}

	// Block obvious traversal attempts before processing
	if strings.Contains(requestedPath, "..") {
		return "", ErrAccessDenied
	}

	// Reject paths with backslashes (Windows-style)
	if strings.ContainsRune(requestedPath, '\\') {
		return "", ErrAccessDenied
	}

	// Clean the requested path component
	cleanedRequest := filepath.Clean(requestedPath)

	// Construct the full path
	fullPath := filepath.Join(s.baseDir, cleanedRequest)

	// Clean the full path to resolve any remaining relative components
	fullPath = filepath.Clean(fullPath)

	// Critical security check: verify the resolved path is within base directory
	// Using HasPrefix on the cleaned, canonical paths ensures no traversal
	if !strings.HasPrefix(fullPath, s.baseDir) {
		return "", ErrAccessDenied
	}

	// Verify the path doesn't point to the base directory itself
	if fullPath == s.baseDir {
		return "", ErrAccessDenied
	}

	// Resolve symlinks and verify again
	realPath, err := filepath.EvalSymlinks(fullPath)
	if err != nil {
		if os.IsNotExist(err) {
			return "", ErrNotFound
		}
		return "", ErrAccessDenied
	}

	// Re-verify after symlink resolution
	if !strings.HasPrefix(realPath, s.baseDir) {
		return "", ErrAccessDenied
	}

	return realPath, nil
}

func (s *SecureFileServer) validateFileAccess(path string) error {
	// Check file extension
	ext := strings.ToLower(filepath.Ext(path))
	if !s.allowedExts[ext] {
		return ErrAccessDenied
	}

	// Check file size
	info, err := os.Stat(path)
	if err != nil {
		return ErrNotFound
	}
	if info.IsDir() {
		return ErrAccessDenied
	}
	if info.Size() > s.maxFileSize {
		return ErrAccessDenied
	}

	return nil
}

func (s *SecureFileServer) logAccess(clientIP, path, result string) {
	s.auditMu.Lock()
	s.auditLog = append(s.auditLog, auditEntry{
		Timestamp: time.Now(),
		ClientIP:  clientIP,
		Path:      path,
		Result:    result,
	})
	s.auditMu.Unlock()
}

// ServeFile handles authenticated file requests with full security validation
func (s *SecureFileServer) ServeFile(w http.ResponseWriter, r *http.Request) {
	clientIP := r.RemoteAddr

	// Rate limiting
	if err := s.checkRateLimit(clientIP); err != nil {
		s.logAccess(clientIP, r.URL.Path, "rate_limited")
		http.Error(w, "Too Many Requests", http.StatusTooManyRequests)
		return
	}

	// Authentication
	token := r.Header.Get("X-Access-Token")
	if err := s.validateToken(token); err != nil {
		s.logAccess(clientIP, r.URL.Path, "auth_failed")
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Only allow GET requests
	if r.Method != http.MethodGet {
		s.logAccess(clientIP, r.URL.Path, "method_not_allowed")
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	// Path sanitization and traversal prevention
	safePath, err := s.sanitizePath(r.URL.Path)
	if err != nil {
		s.logAccess(clientIP, r.URL.Path, "access_denied")
		if errors.Is(err, ErrNotFound) {
			http.Error(w, "Not Found", http.StatusNotFound)
		} else {
			http.Error(w, "Forbidden", http.StatusForbidden)
		}
		return
	}

	// File access validation
	if err := s.validateFileAccess(safePath); err != nil {
		s.logAccess(clientIP, safePath, "file_access_denied")
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	// Serve the file
	f, err := os.Open(safePath)
	if err != nil {
		s.logAccess(clientIP, safePath, "open_failed")
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
		return
	}
	defer f.Close()

	s.logAccess(clientIP, safePath, "success")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Content-Disposition", "attachment")
	io.Copy(w, f)
}
